\n  ELSE\n   SELECT * INTO STRICT m FROM public.marketing_channel_daily_metrics WHERE id=NEW.source_id;\n   IF m.store_id<>v.store_id OR m.metric_date<v.date_from OR m.metric_date>v.date_to\n      OR m.spend<0 OR m.data_source=''estimated'' OR NEW.classification<>''advertising''\n      OR NEW.observed_source<>to_jsonb(m) THEN RAISE EXCEPTION ''Unsupported or stale marketing source''; END IF;\n  END IF;\n END IF;\n RETURN NEW;\nEND;$function$\n","definition":"CREATE TRIGGER immutable_line_cost BEFORE INSERT OR DELETE OR UPDATE ON finance_v1.line_cost_evidence FOR EACH ROW EXECUTE FUNCTION finance_v1.profit_evidence_guard()"},{"name":"ingest_order_evidence_coverage","table":"finance_v1.order_evidence","enabled":"O","function":"CREATE OR REPLACE FUNCTION ingest_v1.invalidate_source_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE old_store uuid; new_store uuid;\nBEGIN\n IF TG_OP=''UPDATE'' AND to_jsonb(OLD)=to_jsonb(NEW) THEN RETURN NEW; END IF;\n IF TG_OP<>''INSERT'' THEN old_store:=OLD.store_id; END IF;\n IF TG_OP<>''DELETE'' THEN new_store:=NEW.store_id; END IF;\n IF old_store IS NOT NULL THEN\n  PERFORM ingest_v1.invalidate_verified_store(old_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=old_store AND NOT needs_recheck;\n END IF;\n IF new_store IS NOT NULL AND new_store IS DISTINCT FROM old_store THEN\n  PERFORM ingest_v1.invalidate_verified_store(new_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=new_store AND NOT needs_recheck;\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n$function$\n","definition":"CREATE TRIGGER ingest_order_evidence_coverage AFTER INSERT OR DELETE OR UPDATE ON finance_v1.order_evidence FOR EACH ROW EXECUTE FUNCTION ingest_v1.invalidate_source_change()"},{"name":"immutable_profit_coverage","table":"finance_v1.profit_component_coverage","enabled":"O","function":"CREATE OR REPLACE FUNCTION finance_v1.prof