XCEPTION ''Expense currency mismatch''; END IF;\n  IF NEW.source_kind=''overhead_entry'' THEN\n   SELECT * INTO STRICT o FROM public.overhead_entries WHERE id=NEW.source_id;\n   SELECT * INTO STRICT c FROM public.overhead_categories WHERE id=o.category_id;\n   IF o.store_id<>v.store_id OR c.store_id<>v.store_id OR o.currency_code<>v.currency\n      OR o.entry_type<>''actual'' OR o.amount<0 OR o.period_start<>v.date_from OR o.period_end<>v.date_to\n      OR NEW.observed_source<>jsonb_build_object(''entry'',to_jsonb(o),''category'',to_jsonb(c))\n      THEN RAISE EXCEPTION ''Unsupported or stale overhead source''; END IF;\n  ELSE\n   SELECT * INTO STRICT m FROM public.marketing_channel_daily_metrics WHERE id=NEW.source_id;\n   IF m.store_id<>v.store_id OR m.metric_date<v.date_from OR m.metric_date>v.date_to\n      OR m.spend<0 OR m.data_source=''estimated'' OR NEW.classification<>''advertising''\n      OR NEW.observed_source<>to_jsonb(m) THEN RAISE EXCEPTION ''Unsupported or stale marketing source''; END IF;\n  END IF;\n END IF;\n RETURN NEW;\nEND;$function$\n","definition":"CREATE TRIGGER immutable_stock_return BEFORE INSERT OR DELETE OR UPDATE ON finance_v1.stock_return_evidence FOR EACH ROW EXECUTE FUNCTION finance_v1.profit_evidence_guard()"},{"name":"ingest_order_coverage","table":"public.orders","enabled":"O","function":"CREATE OR REPLACE FUNCTION ingest_v1.invalidate_source_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE old_store uuid; new_store uuid;\nBEGIN\n IF TG_OP=''UPDATE'' AND to_jsonb(OLD)=to_jsonb(NEW) THEN RETURN NEW; END IF;\n IF TG_OP<>''INSERT'' THEN old_store:=OLD.store_id; END IF;\n IF TG_OP<>''DELETE'' THEN new_store:=NEW.store_id; END IF;\n IF old_store IS NOT NULL THEN\n  PERFORM ingest_v1.invalidate_verified_store(old_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=old_store AND NOT needs_recheck;\n END IF;\n IF new_store IS NOT NULL AND new_store IS DISTINCT FROM old_store THEN\n  PERFORM ingest_v1.invalidate_verified_store(new_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=new_store AND NOT needs_recheck;\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n$function$\n","definition":"CREATE TRIGGER ingest_order_coverage AFTER INSERT OR DELETE OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION ingest_v1.invalidate_source_change()"},{"name":"ingest_refund_coverage","table":"public.refunds","enabled":"O","function":"CREATE OR REPLACE FUNCTION ingest_v1.invalidate_source_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE old_store uuid; new_store uuid;\nBEGIN\n IF TG_OP=''UPDATE'' AND to_jsonb(OLD)=to_jsonb(NEW) THEN RETURN NEW; END IF;\n IF TG_OP<>''INSERT'' THEN old_store:=OLD.store_id; END IF;\n IF TG_OP<>''DELETE'' THEN new_store:=NEW.store_id; END IF;\n IF old_store IS NOT NULL THEN\n  PERFORM ingest_v1.invalidate_verified_store(old_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=old_store AND NOT needs_recheck;\n END IF;\n IF new_store IS NOT NULL AND new_store IS DISTINCT FROM old_store THEN\n  PERFORM ingest_v1.invalidate_verified_store(new_store);\n  UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=new_store AND NOT needs_recheck;\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND;\n$function$\n","definition":"CREATE TRIGGER ingest_refund_coverage AFTER INSERT OR DELETE OR UPDATE ON public.refunds FOR EACH ROW EXECUTE FUNCTION ingest_v1.invalidate_source_change()"},{"name":"ingest_settings_coverage","table":"public.stores","enabled":"O","function":"CREATE OR REPLACE FUNCTION ingest_v1.invalidate_store_settings()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nBEGIN\n PERFORM ingest_v1.invalidate_verified_store(NEW.id);\n UPDATE ingest_v1.heads SET needs_recheck=true WHERE store_id=NEW.id AND NOT needs_recheck;\n RETURN NEW;\nEND;\n$function$\n","definition":"CREATE TRIGGER ingest_settings_coverage AFTER UPDATE ON public.stores FOR EACH ROW WHEN (((old.currency_code IS DISTINCT FROM new.currency_code) OR (old.timezone IS DISTINCT FROM new.timezone) OR (old.shopify_domain IS DISTINCT FROM new.shopify_domain) OR (old.shopify_store_id IS DISTINCT FROM new.shopify_store_id))) EXECUTE FUNCTION ingest_v1.invalidate_store_settings()"}],"constraints":[{"name":"coverage_evidence_check","table":"finance_v1.coverage_evidence","definition":"CHECK ((date_to >= date_from))"},{"name":"coverage_evidence_currency_check","table":"finance_v1.coverage_evidence","definition":"CHECK ((currency ~ ''^[A-Z]{3}$''::text))"},{"name":"coverage_evidence_evidence_ref_check","table":"finance_v1.coverage_evidence","definition":"CHECK ((length(TRIM(BOTH FROM evidence_ref)) > 0))"},{"name":"coverage_evidence_pkey","table":"finance_v1.coverage_evidence","definition":"PRIMARY KEY (store_id, date_from, date_to)"},{"name":"coverage_evidence_store_id_fkey","table":"finance_v1.coverage_evidence","definition":"FOREIGN KEY (store_id) REFERENCES stores(id)"},{"name":"coverage_evidence_verified_by_check","table":"finance_v1.coverage_evidence","definition":"CHECK ((length(TRIM(BOTH FROM verified_by)) > 0))"},{"name":"expense_evidence_canonical_expense_key_check","table":"finance_v1.expense_evidence","definition":"CHECK ((length(TRIM(BOTH FROM canonical_expense_key)) > 0))"},{"name":"expense_evidence_classification_check","table":"finance_v1.expense_evidence","definition":"CHECK ((classification = ANY (ARRAY[''variable''::text, ''advertising''::text, ''overhead''::text, ''depreciation_amortisation''::text, ''excluded_interest''::text, ''excluded_corporation_tax''::text])))"},{"name":"expense_evidence_currency_check","table":"finance_v1.expense_evidence","definition":"CHECK ((currency ~ ''^[A-Z]{3}$''::text))"},{"name":"expense_evidence_evidence_ref_check","table":"finance_v1.expense_evidence","definition":"